import { Input } from "./types";

type Output = { avg: number };

export const inputs = ["msgid_0x6b1_data"];

export const output = "avg";

let data = 0.0;

let rolling_window: number[] = [];
const WINDOW_SIZE = 25;

type InputEvent = Input<"msgid_0x6b1_data">;

export default function script(event: InputEvent): Output {
  data = event.message.Pack_Summed_Voltage * event.message.Pack_Current;

  // update rolling window
  if (!isNaN(data) && isFinite(data)) {
    rolling_window.push(data);
    if (rolling_window.length > WINDOW_SIZE) {
      rolling_window.shift(); // remove oldest
    }
  }

  // compute rolling average
  const window_avg =
    rolling_window.reduce((a, b) => a + b, 0) / rolling_window.length;

  return { avg: window_avg };
}

